1	//! The `trailers` subcommand: rewrite a range of work commits' trailers
2	//! to what `vc-x1` stamps today, only their descriptions changing.
3	//!
4	//! - `ochid:` becomes the partner's bare change id, so a label or URL
5	//!   form goes.
6	//! - `ocid:` links the agent commit named: its SHA, or the placeholder
7	//!   while it is still the uncommitted agent `@`.
8	//! - `pcid:` links each parent, by its SHA now, so the range goes oldest
9	//!   first, a commit's rewrite having changed the SHA its child links.
10	//! - A trailer naming nothing that resolves, a `lost` or an old short
11	//!   id, is left as it is, with no guessing and no `ocid:`.
12	//!
13	//! A Land runs [`update`] over the cycle too, with `add` off, so it only
14	//! refreshes the links a commit has, `--no-url-trailer`'s having none.
15	//! This changes the work repo alone, since an agent commit carries only
16	//! change ids, which a rewrite keeps.
17	
18	use std::path::PathBuf;
19	
20	use clap::Args;
21	use log::{debug, info, warn};
22	
23	use crate::context::Context;
24	use crate::desc_helpers::{
25	    DEFAULT_ID_LEN, Trailers, commit_url, extract_bare_id, ocid_placeholder_for, pcids_for,
26	    repo_url_for, with_trailers,
27	};
28	use crate::jj;
29	use crate::options_flags::dry_run::DryRunFlag;
30	use crate::pair::Pair;
31	use crate::subcommand::SubcommandRunner;
32	
33	/// Update the trailers of a range of work commits to what is stamped
34	/// today, only their descriptions changing.
35	#[derive(Args, Debug)]
36	pub struct TrailersArgs {
37	    /// Rewrite the trailers, the one thing this does so far
38	    #[arg(long, required = true)]
39	    pub update: bool,
40	
41	    /// The commits: a bookmark or revision, those above the trunk up to
42	    /// it, or a revset with `..` or `::`, as written [default: those
43	    /// above the trunk up to `@-`]
44	    #[arg(long, value_name = "BM|REV")]
45	    pub range: Option<String>,
46	
47	    /// Rewrite a commit already on the trunk's remote, which is refused
48	    /// without it
49	    #[arg(long)]
50	    pub yes: bool,
51	
52	    /// Where: a path in the workspace, its root or either repo [default:
53	    /// the current directory]
54	    #[arg(short = 'R', long, value_name = "PATH")]
55	    pub repo: Option<PathBuf>,
56	
57	    /// Print each description it would write, and change nothing
58	    #[command(flatten)]
59	    pub dry_run: DryRunFlag,
60	}
61	
62	/// Inputs to the trailers op, flat, owned, clap-free.
63	#[derive(Debug)]
64	pub struct TrailersParams {
65	    pub pair: Pair,
66	    pub range: Option<String>,
67	    pub yes: bool,
68	    pub dry_run: bool,
69	}
