71	impl SubcommandRunner for TrailersArgs {
72	    type Params = TrailersParams;
73	
74	    /// Resolve the workspace's pair.
75	    fn to_params(&self) -> Result<Self::Params, String> {
76	        Ok(TrailersParams {
77	            pair: crate::pair::resolve_pair(self.repo.as_deref()).map_err(|e| e.to_string())?,
78	            range: self.range.clone(),
79	            yes: self.yes,
80	            dry_run: self.dry_run.value,
81	        })
82	    }
83	
84	    /// Run the `trailers` op.
85	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
86	        trailers(ctx, params)
87	    }
88	}
