1	//! The `trailers` subcommand: rewrite a range of work commits' trailers
2	//! to what `vc-x1` stamps today, only their descriptions changing.
3	//!
4	//! - `ochid:` becomes the partner's bare change id, so a label or URL
5	//!   form goes.
6	//! - `ocid:` links the agent commit named: its SHA, or the placeholder
7	//!   while it is still the uncommitted agent `@`.
8	//! - `pcid:` links each parent, by its SHA now, so the range goes oldest
9	//!   first, a commit's rewrite having changed the SHA its child links.
10	//! - A trailer naming nothing that resolves, a `lost` or an old short
11	//!   id, is left as it is, with no guessing and no `ocid:`.
12	//!
13	//! A Land runs [`update`] over the cycle too, with `add` off, so it only
14	//! refreshes the links a commit has, `--no-url-trailer`'s having none.
15	//! This changes the work repo alone, since an agent commit carries only
16	//! change ids, which a rewrite keeps.
17	
18	use std::path::PathBuf;
19	
20	use clap::Args;
21	use log::{debug, info, warn};
22	
23	use crate::context::Context;
24	use crate::desc_helpers::{
25	    DEFAULT_ID_LEN, Trailers, commit_url, extract_bare_id, ocid_placeholder_for, pcids_for,
26	    repo_url_for, with_trailers,
27	};
28	use crate::jj;
29	use crate::options_flags::dry_run::DryRunFlag;
30	use crate::pair::Pair;
31	use crate::subcommand::SubcommandRunner;
32	
33	/// Update the trailers of a range of work commits to what is stamped
34	/// today, only their descriptions changing.
35	#[derive(Args, Debug)]
36	pub struct TrailersArgs {
37	    /// Rewrite the trailers, the one thing this does so far
38	    #[arg(long, required = true)]
39	    pub update: bool,
40	
41	    /// The commits: a bookmark or revision, those above the trunk up to
42	    /// it, or a revset with `..` or `::`, as written [default: those
43	    /// above the trunk up to `@-`]
44	    #[arg(long, value_name = "BM|REV")]
45	    pub range: Option<String>,
46	
47	    /// Rewrite a commit already on the trunk's remote, which is refused
48	    /// without it
49	    #[arg(long)]
50	    pub yes: bool,
51	
52	    /// Where: a path in the workspace, its root or either repo [default:
53	    /// the current directory]
54	    #[arg(short = 'R', long, value_name = "PATH")]
55	    pub repo: Option<PathBuf>,
56	
57	    /// Print each description it would write, and change nothing
58	    #[command(flatten)]
59	    pub dry_run: DryRunFlag,
60	}
61	
62	/// Inputs to the trailers op, flat, owned, clap-free.
63	#[derive(Debug)]
64	pub struct TrailersParams {
65	    pub pair: Pair,
66	    pub range: Option<String>,
67	    pub yes: bool,
68	    pub dry_run: bool,
69	}
70	
71	impl SubcommandRunner for TrailersArgs {
72	    type Params = TrailersParams;
73	
74	    /// Resolve the workspace's pair.
75	    fn to_params(&self) -> Result<Self::Params, String> {
76	        Ok(TrailersParams {
77	            pair: crate::pair::resolve_pair(self.repo.as_deref()).map_err(|e| e.to_string())?,
78	            range: self.range.clone(),
79	            yes: self.yes,
80	            dry_run: self.dry_run.value,
81	        })
82	    }
83	
84	    /// Run the `trailers` op.
85	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
86	        trailers(ctx, params)
87	    }
88	}
89	
90	/// Entry point: resolve the range, refuse a rewrite of the trunk's
91	/// remote unless `--yes`, and update.
92	pub fn trailers(
93	    ctx: &mut Context,
94	    params: &TrailersParams,
95	) -> Result<(), Box<dyn std::error::Error>> {
96	    debug!("trailers: enter {params:?}");
97	    let work = params.pair.work.as_path();
98	    let trunk = crate::commit::configured_trunk(work)?;
99	    let revset = match &params.range {
100	        Some(r) if r.contains("..") || r.contains("::") => r.clone(),
101	        Some(r) => format!("{trunk}..({r})"),
102	        None => format!("{trunk}..@-"),
103	    };
104	    let remote_trunk = format!("{trunk}@origin");
105	    if !params.yes
106	        && jj::rev_exists(work, &remote_trunk)?
107	        && jj::matches(work, &format!("({revset}) & ::{remote_trunk}"))?
108	    {
109	        return Err(format!(
110	            "trailers: '{revset}' reaches commits on {remote_trunk}, so this would rewrite the \
111	             trunk's published history: --yes does it anyway"
112	        )
113	        .into());
114	    }
115	    if repo_url_for(&params.pair.agent)?.is_none() {
116	        info!("trailers: the agent repo has no `origin` to link, so no `ocid:`");
117	    }
118	    if repo_url_for(work)?.is_none() {
119	        info!("trailers: the work repo has no `origin` to link, so no `pcid:`");
120	    }
121	    let changed = update(
122	        ctx,
123	        &params.pair,
124	        &Update {
125	            label: "trailers",
126	            revset: &revset,
127	            add: true,
128	            agent_at_committed: false,
129	            dry: params.dry_run,
130	        },
131	    )?;
132	    let verb = if params.dry_run {
133	        "would change"
134	    } else {
135	        "changed"
136	    };
137	    info!("trailers: {verb} {changed} commit(s) in '{revset}'");
138	    Ok(())
139	}
140	
141	/// What [`update`] does, and to which commits.
142	pub(crate) struct Update<'a> {
143	    /// How messages name the command.
144	    pub label: &'a str,
145	    /// The work commits.
146	    pub revset: &'a str,
147	    /// Stamp `ocid:` and `pcid:` on a commit lacking them, which a Land
148	    /// does not, a commit with no links having asked for none.
149	    pub add: bool,
150	    /// A dry run of a Land: the agent `@` counts as committed, so what
151	    /// names it reads as set, though no SHA exists to show.
152	    pub agent_at_committed: bool,
153	    pub dry: bool,
154	}
155	
156	/// Rewrite the trailers of each commit in the range, oldest first,
157	/// its tree checked unchanged, and return how many changed. Rerunning
158	/// finds nothing to do. A failure restores the work repo.
159	pub(crate) fn update(
160	    ctx: &mut Context,
161	    pair: &Pair,
162	    u: &Update,
163	) -> Result<usize, Box<dyn std::error::Error>> {
164	    let (work, agent) = (pair.work.as_path(), pair.agent.as_path());
165	    let label = u.label;
166	    // By change id, since a rewrite changes the SHAs of what is above it.
167	    let chids = jj::cids_of(work, u.revset)?
168	        .iter()
169	        .map(|rev| jj::chid_of(work, rev))
170	        .collect::<Result<Vec<_>, _>>()?;
171	    let agent_url = repo_url_for(agent)?;
172	    let agent_at = jj::chid_of(agent, "@")?;
173	    let placeholder = ocid_placeholder_for(agent)?;
174	    let snapshot = crate::pair::Snapshot::take(work)?;
175	    let mut changed = 0;
176	    for chid in &chids {
177	        let desc = jj::desc_of(work, chid)?;
178	        let old = Trailers::of(&desc);
179	        if old.ochids.is_empty() {
180	            continue;
181	        }
182	        let resolves = |id: &str| -> Result<bool, Box<dyn std::error::Error>> {
183	            Ok(id.len() == DEFAULT_ID_LEN && jj::rev_exists(agent, id)?)
184	        };
185	        let mut ochids = Vec::new();
186	        for value in &old.ochids {
187	            let id = extract_bare_id(value);
188	            ochids.push(match resolves(id)? {
189	                true => id.to_string(),
190	                false => value.clone(),
191	            });
192	        }
193	        let partner = extract_bare_id(&ochids[ochids.len() - 1]).to_string();
194	        let ocid = if !u.add && old.ocid.is_none() {
195	            None
196	        } else if !resolves(&partner)? {
197	            old.ocid.clone()
198	        } else if partner == agent_at && u.agent_at_committed {
199	            agent_url
200	                .as_deref()
201	                .map(|url| commit_url(url, "<the agent commit's SHA>"))
202	        } else if partner == agent_at {
203	            placeholder.clone()
204	        } else {
205	            match &agent_url {
206	                Some(url) => Some(commit_url(url, &jj::cid_of(agent, &partner)?)),
207	                None => old.ocid.clone(),
208	            }
209	        };
210	        let pcids = if u.add || !old.pcids.is_empty() {
211	            pcids_for(work, &jj::parent_cids_of(work, chid)?)?
212	        } else {
213	            Vec::new()
214	        };
215	        let new = with_trailers(
216	            &desc,
217	            &Trailers {
218	                ochids,
219	                ocid,
220	                pcids,
221	            },
222	        );
223	        if new == desc {
224	            continue;
225	        }
226	        changed += 1;
227	        if u.dry {
228	            info!("{label}: [dry-run] {chid}:\n{new}");
229	            continue;
230	        }
231	        if crate::pair::is_published(work, chid)? {
232	            warn!("{label}: {chid} is published, so its copy on the remote goes stale");
233	        }
234	        info!("{label}: update the trailers of {chid}");
235	        let tree = jj::tree_of(work, chid)?;
236	        let stamped = ctx.session(work)?.describe(chid, &new).and_then(|_| {
237	            match jj::tree_of(work, chid)? == tree {
238	                true => Ok(()),
239	                false => {
240	                    Err(format!("{label}: updating {chid}'s trailers changed its tree").into())
241	                }
242	            }
243	        });
244	        if let Err(e) = stamped {
245	            snapshot.restore(label, e.as_ref());
246	            return Err(e);
247	        }
248	    }
249	    Ok(changed)
250	}
251	
252	#[cfg(test)]
253	mod tests {
254	    use super::*;
255	    use crate::test_helpers::{Fixture, chid, description, git_ok, jj_ok, test_ctx};
256	    use std::fs;
257	
258	    const AGENT_URL: &str = "https://github.com/o/r.agent-session";
259	    const WORK_URL: &str = "https://github.com/o/r";
260	
261	    fn hosted(fx: &Fixture) {
262	        git_ok(&fx.work, &["remote", "set-url", "origin", WORK_URL]);
263	        git_ok(&fx.bot, &["remote", "set-url", "origin", AGENT_URL]);
264	    }
265	
266	    fn cid(repo: &std::path::Path, rev: &str) -> String {
267	        jj::cid_of(repo, rev).expect("cid")
268	    }
269	
270	    /// A rung by hand, carrying `trailer`, with a custom one below it.
271	    fn rung(fx: &Fixture, name: &str, trailer: &str) -> String {
272	        fs::write(fx.work.join(format!("{name}.txt")), "x\n").expect("write");
273	        let desc = format!("feat: {name}\n\nBody.\n\nochid: {trailer}\nreviewed-by: wink\n");
274	        jj_ok(&fx.work, &["commit", "-m", &desc]);
275	        chid(&fx.work, "@-")
276	    }
277	
278	    fn params(fx: &Fixture, range: &str, dry_run: bool) -> TrailersParams {
279	        TrailersParams {
280	            pair: Pair {
281	                work: fx.work.clone(),
282	                agent: fx.bot.clone(),
283	            },
284	            range: Some(range.to_string()),
285	            yes: false,
286	            dry_run,
287	        }
288	    }
289	
290	    /// Old forms become the bare change id, `ocid:` the placeholder for
291	    /// the agent `@` and a SHA for a commit made, `pcid:` each parent's
292	    /// SHA as rewritten, the custom trailer kept, change ids and trees
293	    /// unchanged, a dry run doing none of it, and a rerun nothing.
294	    #[test]
295	    fn a_range_takes_todays_trailers() {
296	        let fx = Fixture::new("trailers-update");
297	        hosted(&fx);
298	        let made = chid(&fx.bot, "@-");
299	        let made_sha = cid(&fx.bot, "@-");
300	        let at = chid(&fx.bot, "@");
301	        let first = rung(&fx, "first", &format!("/.claude/{made}"));
302	        let second = rung(&fx, "second", &format!("{AGENT_URL}#{at}"));
303	        let lost = rung(&fx, "third", "/.claude/lost");
304	        let tree = jj::tree_of(&fx.work, &second).expect("tree");
305	
306	        let before = description(&fx.work, &first);
307	        let n = trailers(&mut test_ctx(), &params(&fx, "@-", true)).ok();
308	        assert!(n.is_some(), "a dry run");
309	        assert_eq!(
310	            description(&fx.work, &first),
311	            before,
312	            "a dry run writes none"
313	        );
314	
315	        trailers(&mut test_ctx(), &params(&fx, "@-", false)).expect("updated");
316	        let parent = cid(&fx.work, "main");
317	        assert!(
318	            description(&fx.work, &first).trim_end().ends_with(&format!(
319	                "\n\nochid: {made}\nocid: {AGENT_URL}/commit/{made_sha}\npcid: {WORK_URL}/commit/{parent}\nreviewed-by: wink"
320	            )),
321	            "{}",
322	            description(&fx.work, &first)
323	        );
324	        let parent = cid(&fx.work, &first);
325	        assert!(
326	            description(&fx.work, &second).trim_end().ends_with(&format!(
327	                "\n\nochid: {at}\nocid: {AGENT_URL}/commit/xxxx\npcid: {WORK_URL}/commit/{parent}\nreviewed-by: wink"
328	            )),
329	            "{}",
330	            description(&fx.work, &second)
331	        );
332	        let third = description(&fx.work, &lost);
333	        assert!(third.contains("ochid: /.claude/lost\n"), "{third}");
334	        assert!(!third.contains("ocid:"), "{third}");
335	        assert_eq!(jj::tree_of(&fx.work, &second).expect("tree"), tree);
336	        assert!(jj::is_empty(&fx.work, "@").expect("empty"));
337	
338	        let sha = cid(&fx.work, &second);
339	        trailers(&mut test_ctx(), &params(&fx, "@-", false)).expect("rerun");
340	        assert_eq!(cid(&fx.work, &second), sha, "a rerun rewrites nothing");
341	    }
342	
343	    /// With no `--range` it reaches `@-`, past a bookmark below it, and a
344	    /// local `origin` links by `file:///`.
345	    #[test]
346	    fn the_default_range_reaches_the_work_head() {
347	        let fx = Fixture::new("trailers-default");
348	        let made = chid(&fx.bot, "@-");
349	        let first = rung(&fx, "first", &format!("/.claude/{made}"));
350	        jj_ok(&fx.work, &["bookmark", "set", "topic", "-r", "@-"]);
