1	//! The `validate-desc` subcommand: scan a revision range and check
2	//! each commit's `ochid:` trailer against the cross-referenced
3	//! repo: flagging missing, malformed, or dangling links.
4	//!
5	//! Read-only diagnostic; exits non-zero if any commit has issues.
6	//! The bot's "did the ochid wiring stay consistent?" check.
7	//!
8	//! The first command under the scope rule: `-s` is required and
9	//! says whose commits are checked, `w`, `a`, or `b` for both
10	//! directions, one table per side under its label, and `-R` is
11	//! optional and says where. `-s p` is refused, since a plain repo
12	//! has no other repo to check against.
13	
14	use std::path::{Path, PathBuf};
15	
16	use clap::Args;
17	use jj_lib::object_id::ObjectId;
18	use jj_lib::repo::Repo;
19	
20	use log::{debug, info};
21	
22	use crate::common;
23	use crate::context::Context;
24	use crate::desc_helpers::{
25	    DEFAULT_ID_LEN, OCID_PLACEHOLDER, TitleMatch, Trailers, extract_bare_id, extract_ochids,
26	    find_matching_commit, ochid_forms_for, ochid_prefix_for, repo_url_for, validate_ochid,
27	};
28	use crate::jj;
29	use crate::options_flags::scope::{REPO_SCOPE_FORMS, RepoScope, repo_scope_parser, side_keyword};
30	use crate::subcommand::SubcommandRunner;
31	
32	#[derive(Args, Debug)]
33	pub struct ValidateDescArgs {
34	    /// Retired: the revision, now `-r`, refused naming it.
35	    #[arg(value_name = "RETIRED", hide = true)]
36	    pub retired_rev: Option<String>,
37	
38	    /// Retired: the count, now `-n`, refused naming it, kept as typed.
39	    #[arg(value_name = "RETIRED", hide = true)]
40	    pub retired_count: Option<String>,
41	
42	    /// Revision(s) to scan, with optional .. notation
43	    #[arg(short, long, default_value = "@")]
44	    pub revision: String,
45	
46	    /// Number of commits to scan
47	    #[arg(short = 'n', long = "commits", value_name = "COMMITS")]
48	    pub limit: Option<usize>,
49	
50	    /// Where: a path in the workspace, its root or either repo
51	    /// [default: the current directory]
52	    #[arg(short = 'R', long, value_name = "PATH")]
53	    pub repo: Option<PathBuf>,
54	
55	    /// Whose commits are checked, required: `w|work`, `a|agent`, or
56	    /// `b|both`, each side against the other. `p|por` is refused,
57	    /// a plain repo having no other repo
58	    #[arg(
59	        short = 's',
60	        long,
61	        value_name = "SCOPE",
62	        value_parser = repo_scope_parser(&["work", "agent", "both"]),
63	        required = true,
64	        help = format!("Whose commits are checked, required: {REPO_SCOPE_FORMS}, `p` refused")
65	    )]
66	    pub scope: RepoScope,
67	
68	    /// Path to the other repo, for one side [default: the workspace's
69	    /// other side]
70	    #[arg(long = "other-repo", value_name = "PATH")]
71	    pub other_repo: Option<PathBuf>,
72	
73	    /// Expected changeID length
74	    #[arg(long = "id-len", default_value_t = DEFAULT_ID_LEN)]
75	    pub id_len: usize,
76	}
77	
78	/// Inputs to the validate-desc op, flat, owned, clap-free.
79	///
80	/// Mirrors `ValidateDescArgs`: `--revision` / `--commits`
81	/// (`revision` / `limit`), `--other-repo`, `--id-len`, and `-s`
82	/// with `-R` resolved into `repos`, each side's label and path in
83	/// scope order. The retired positionals are refused before it is
84	/// built.
85	#[derive(Debug)]
86	pub struct ValidateDescParams {
87	    pub revision: String,
88	    pub limit: Option<usize>,
89	    pub repos: Vec<(String, PathBuf)>,
90	    pub other_repo: Option<PathBuf>,
91	    pub id_len: usize,
92	}
93	
94	impl TryFrom<&ValidateDescArgs> for ValidateDescParams {
95	    type Error = String;
96	
97	    /// Resolve `-s` and `-R` into the sides to check, labeled by
98	    /// their keywords, and copy the rest over. `-s p` is refused
99	    /// here, before anything is read.
100	    fn try_from(a: &ValidateDescArgs) -> Result<Self, String> {
101	        crate::options_flags::retired_positional::refuse_rev_count(
102	            "validate-desc",
103	            a.retired_rev.as_deref(),
104	            a.retired_count.as_deref(),
105	        )?;
106	        let sides = match &a.scope {
107	            RepoScope::Sides(s) => s,
108	            RepoScope::Por => {
109	                return Err(
110	                    "-s p: a plain repo has no other repo to check its descriptions \
111	                            against. validate-desc takes `-s w|a|b` in a dual workspace"
112	                        .to_string(),
113	                );
114	            }
115	        };
116	        let paths = crate::common::resolve_scoped_repos(&a.scope, a.repo.as_deref())
117	            .map_err(|e| e.to_string())?;
118	        let repos = sides
119	            .0
120	            .iter()
121	            .zip(paths)
122	            .map(|(side, path)| (side_keyword(*side).to_string(), path))
123	            .collect();
124	        Ok(Self {
125	            revision: a.revision.clone(),
126	            limit: a.limit,
127	            repos,
128	            other_repo: a.other_repo.clone(),
129	            id_len: a.id_len,
130	        })
131	    }
132	}
