146	impl SubcommandRunner for ValidateDescArgs {
147	    type Params = ValidateDescParams;
148	
149	    /// Delegate to the `TryFrom<&ValidateDescArgs>` impl above.
150	    fn to_params(&self) -> Result<Self::Params, String> {
151	        ValidateDescParams::try_from(self)
152	    }
153	
154	    /// Run the existing `validate_desc` op.
155	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
156	        validate_desc(ctx, params)
157	    }
