193	/// What [`link_findings`] found: what is wrong, and what is only worth
194	/// saying.
195	#[derive(Debug, Default)]
196	struct LinkFindings {
197	    wrong: Vec<String>,
198	    notes: Vec<String>,
199	}
200	
201	/// Check a work commit's `ocid:` and `pcid:` links, offline, from the two
202	/// repos and what they know of their remotes. Having none is not wrong,
203	/// an older or `--no-url-trailer` commit having none. A wrong link is
204	/// repaired by `vc-x1 trailers --update`.
205	///
206	/// - `ocid:` names the agent repo's `origin`, and its SHA is the commit
207	///   the last `ochid:` names, or the placeholder while that is the
208	///   uncommitted agent `@`. An agent commit not yet on a remote is a note.
209	/// - `pcid:` names the work repo's `origin`, and its SHAs are the commit's
210	///   parents, every one, in parent order.
211	fn link_findings(
212	    work: &Path,
213	    agent: &Path,
214	    commit: &str,
215	    desc: &str,
216	    id_len: usize,
217	) -> Result<LinkFindings, Box<dyn std::error::Error>> {
218	    let mut found = LinkFindings::default();
219	    let trailers = Trailers::of(desc);
220	    let split = |value: &str| {
221	        value
222	            .rsplit_once("/commit/")
223	            .map(|(url, sha)| (url.to_string(), sha.to_string()))
224	    };
225	    if let Some(ocid) = &trailers.ocid {
226	        match split(ocid) {
227	            None => found.wrong.push(format!("ocid: not a commit link: {ocid}")),
228	            Some((url, sha)) => {
229	                if let Some(want) = repo_url_for(agent)?
230	                    && url != want
231	                {
232	                    found.wrong.push(format!("ocid: names {url}, not {want}"));
233	                }
234	                let partner = trailers.ochids.last().map(|o| extract_bare_id(o));
235	                let partner = partner.filter(|id| {
236	                    id.len() == id_len && id.chars().all(|c| c.is_ascii_alphanumeric())
237	                });
238	                if let Some(partner) = partner
239	                    && jj::rev_exists(agent, partner)?
240	                {
241	                    let actual = jj::cid_of(agent, partner)?;
242	                    let uncommitted = jj::chid_of(agent, "@")? == partner;
243	                    if uncommitted && sha != OCID_PLACEHOLDER {
244	                        found.wrong.push(format!(
245	                            "ocid: has {sha}, and {partner} is the uncommitted agent @"
246	                        ));
247	                    } else if !uncommitted && sha == OCID_PLACEHOLDER {
248	                        found.wrong.push(format!(
249	                            "ocid: placeholder, and {partner} is committed at {actual}"
250	                        ));
251	                    } else if !uncommitted && sha != actual {
252	                        found
253	                            .wrong
254	                            .push(format!("ocid: has {sha}, and {partner} is at {actual}"));
255	                    } else if !uncommitted
256	                        && !jj::matches(agent, &format!("{actual} & ::remote_bookmarks()"))?
257	                    {
258	                        found
259	                            .notes
260	                            .push(format!("the agent commit {actual} is not on a remote yet"));
261	                    }
262	                }
263	            }
264	        }
265	    }
266	    if !trailers.pcids.is_empty() {
267	        let root = jj::cid_of(work, "root()")?;
268	        let parents: Vec<String> = jj::parent_cids_of(work, commit)?
269	            .into_iter()
270	            .filter(|parent| *parent != root)
271	            .collect();
272	        let want_url = repo_url_for(work)?;
273	        let mut shas = Vec::new();
274	        for pcid in &trailers.pcids {
275	            match split(pcid) {
276	                None => found.wrong.push(format!("pcid: not a commit link: {pcid}")),
277	                Some((url, sha)) => {
278	                    if let Some(want) = &want_url
279	                        && url != *want
280	                    {
281	                        found.wrong.push(format!("pcid: names {url}, not {want}"));
282	                    }
283	                    shas.push(sha);
284	                }
285	            }
286	        }
287	        if shas != parents {
288	            found.wrong.push(format!(
289	                "pcid: has [{}], and the parents are [{}]",
290	                shas.join(", "),
291	                parents.join(", ")
292	            ));
293	        }
294	    }
295	    Ok(found)
296	}
