671	    /// Every `ochid:` is checked, not only the last, and a wrong link is
672	    /// an issue the run fails on.
673	    #[test]
674	    fn every_ochid_is_checked_and_a_wrong_link_fails_the_run() {
675	        let fx = Fixture::new("vdesc-all");
676	        let ctx = Context::load().expect("load user config");
677	        let work_at = chid(&fx.work, "@-");
678	        let parse_params = |scope: &str, repo: &Path| {
679	            let mut a = parse(&["vc-x1", "validate-desc", "-r", "@", "-s", scope]).expect("parses");
680	            a.repo = Some(repo.to_path_buf());
681	            ValidateDescParams::try_from(&a).expect("params")
682	        };
683	        let describe = |desc: &str| jj_ok(&fx.bot, &["describe", "-m", desc]);
684	        describe(&format!("feat: x\n\nochid: {work_at}\nochid: {work_at}\n"));
685	        validate_desc(&ctx, &parse_params("a", &fx.bot)).expect("both resolve");
686	        describe(&format!(
687	            "feat: x\n\nochid: zzzzzzzzzzzk\nochid: {work_at}\n"
688	        ));
689	        validate_desc(&ctx, &parse_params("a", &fx.bot)).expect_err("the first does not");
690	
691	        let at = chid(&fx.bot, "@");
692	        let desc = format!("feat: x\n\nochid: {at}\npcid: file:///no/such/commit/abc\n");
693	        jj_ok(&fx.work, &["describe", "-m", &desc]);
694	        validate_desc(&ctx, &parse_params("w", &fx.work)).expect_err("a wrong pcid");
695	    }
696	
697	    /// A URL-form trailer passes when its ID resolves in the other
698	    /// repo and fails when it does not. With a hosted `origin` there,
699	    /// its URL must name that repo too, and with none it is not checked.
700	    #[test]
701	    fn a_url_form_trailer_is_valid_when_it_names_the_repo_and_its_id_resolves() {
702	        let fx = Fixture::new("vdesc-url");
703	        let ctx = Context::load().expect("load user config");
704	        let mut a = parse(&["vc-x1", "validate-desc", "-r", "@", "-s", "w"]).expect("parses");
705	        a.repo = Some(fx.work.clone());
706	        let params = ValidateDescParams::try_from(&a).expect("params");
707	        let url = "https://example.com/o/r.agent-session";
708	        let agent_at = chid(&fx.bot, "@");
709	        let describe = |value: &str| {
710	            let desc = format!("feat: x\n\nochid: {value}\n");
711	            jj_ok(&fx.work, &["describe", "-m", &desc]);
712	        };
713	
714	        describe(&format!("{url}#{agent_at}"));
715	        validate_desc(&ctx, &params).expect("a local origin: the ID alone is checked");
716	
717	        describe(&format!("{url}#zzzzzzzzzzzk"));
718	        validate_desc(&ctx, &params).expect_err("the ID resolves to nothing");
719	
720	        git_ok(
721	            &fx.bot,
722	            &["remote", "set-url", "origin", &format!("{url}.git")],
723	        );
724	        describe(&format!("{url}#{agent_at}"));
725	        validate_desc(&ctx, &params).expect("it names the repo, canonically");
726	
727	        describe(&format!("https://example.com/o/other#{agent_at}"));
728	        validate_desc(&ctx, &params).expect_err("it names another repo");
729	
730	        describe(&format!("/.claude/{agent_at}"));
731	        validate_desc(&ctx, &params).expect("the published label stays valid");
732	    }
733	
734	    /// With no URL to stamp the path form names the directory, and it
735	    /// is valid beside the published label.
736	    #[test]
737	    fn the_path_form_names_the_directory() {
738	        let fx = Fixture::new("vdesc-path");
739	        let ctx = Context::load().expect("load user config");
740	        let mut a = parse(&["vc-x1", "validate-desc", "-r", "@", "-s", "w"]).expect("parses");
741	        a.repo = Some(fx.work.clone());
742	        let params = ValidateDescParams::try_from(&a).expect("params");
743	        let dir = fx
744	            .bot
745	            .file_name()
746	            .and_then(|n| n.to_str())
747	            .expect("a directory name");
748	        let desc = format!("feat: x\n\nochid: /{dir}/{}\n", chid(&fx.bot, "@"));
749	        jj_ok(&fx.work, &["describe", "-m", &desc]);
750	        validate_desc(&ctx, &params).expect("the directory's own name");
751	    }
752	}
