33	pub struct ValidateDescArgs {
34	    /// Retired: the revision, now `-r`, refused naming it.
35	    #[arg(value_name = "RETIRED", hide = true)]
36	    pub retired_rev: Option<String>,
37	
38	    /// Retired: the count, now `-n`, refused naming it, kept as typed.
39	    #[arg(value_name = "RETIRED", hide = true)]
40	    pub retired_count: Option<String>,
41	
42	    /// Revision(s) to scan, with optional .. notation
43	    #[arg(short, long, default_value = "@")]
44	    pub revision: String,
45	
46	    /// Number of commits to scan
47	    #[arg(short = 'n', long = "commits", value_name = "COMMITS")]
48	    pub limit: Option<usize>,
