53	    pub repo: Option<PathBuf>,
54	
55	    /// Whose commits are checked, required: `w|work`, `a|agent`, or
56	    /// `b|both`, each side against the other. `p|por` is refused,
57	    /// a plain repo having no other repo
58	    #[arg(
59	        short = 's',
60	        long,
61	        value_name = "SCOPE",
62	        value_parser = repo_scope_parser(&["work", "agent", "both"]),
63	        required = true,
64	        help = format!("Whose commits are checked, required: {REPO_SCOPE_FORMS}, `p` refused")
65	    )]
66	    pub scope: RepoScope,
67	
68	    /// Path to the other repo, for one side [default: the workspace's
69	    /// other side]
70	    #[arg(long = "other-repo", value_name = "PATH")]
71	    pub other_repo: Option<PathBuf>,
72	
73	    /// Expected changeID length
74	    #[arg(long = "id-len", default_value_t = DEFAULT_ID_LEN)]
75	    pub id_len: usize,
