134	/// Status of a single commit's ochid validation.
135	enum CommitStatus {
136	    Ok,
137	    Lost,                     // ochid marked as "lost" (unrecoverable)
138	    None_,                    // ochid marked as "none" (no counterpart)
139	    NeedsFixed(String),       // summary of issues
140	    MissingNoTitle,           // no ochid, no title to match on
141	    MissingNoMatch,           // no ochid, no title match in other repo
142	    MissingAmbiguous(usize),  // no ochid, multiple title matches
143	    MissingWithMatch(String), // no ochid, unique title match found
144	}
