298	/// Scan one side's revision range against its other repo and print
299	/// the table, returning how many commits have issues. A side with
300	/// no other repo, a single-repo workspace, prints a notice and
301	/// counts nothing.
302	fn validate_side(
303	    params: &ValidateDescParams,
304	    repo_path: &Path,
305	) -> Result<usize, Box<dyn std::error::Error>> {
306	    let (workspace, repo) = common::load_repo(repo_path)?;
307	
308	    // Resolve other repo: --other-repo flag, or side-aware
309	    // resolution from the workspace config (the work repo pairs
310	    // with the bot repo and vice versa). A single-repo / POR
311	    // workspace has no bot side: nothing to validate against, so
312	    // the command no-ops instead of erroring (por equalization;
313	    // topology from the workspace config, not a flag).
314	    let other_repo_path = match &params.other_repo {
315	        Some(p) => p.clone(),
316	        None => match common::other_repo_path(repo_path)? {
317	            Some(p) => p,
318	            None => {
319	                info!("validate-desc: single-repo workspace (no bot side), nothing to validate");
320	                return Ok(0);
321	            }
322	        },
323	    };
324	
325	    let (other_workspace, other_repo) = common::load_repo(&other_repo_path)?;
326	    let other_prefix = ochid_prefix_for(&other_repo_path)?;
327	    let other_forms = ochid_forms_for(&other_repo_path)?;
328	
329	    let spec = common::resolve_spec(&params.revision, params.limit);
330	
331	    let (ids, _anchor_index) = common::collect_ids(
332	        &workspace,
333	        &repo,
334	        &spec.rev,
335	        spec.desc_count,
336	        spec.anc_count,
337	    )?;
338	    if ids.is_empty() {
339	        return Err(format!("no commits found for revision '{}'", params.revision).into());
340	    }
341	
342	    let root_id = repo.store().root_commit_id().clone();
343	    let mut valid = 0;
344	    let mut lost = 0;
345	    let mut none = 0;
346	    let mut issues_count = 0;
347	    let mut missing = 0;
348	
349	    let col_header = "STAT CHANGEID      TITLE";
350	    info!("{col_header}");
351	
352	    for commit_id in &ids {
353	        if *commit_id == root_id {
354	            continue;
355	        }
356	        let commit = repo.store().get_commit(commit_id)?;
357	        let desc = commit.description();
358	        let change_hex = jj_lib::hex_util::encode_reverse_hex(commit.change_id().as_bytes());
359	        let change_short = &change_hex[..change_hex.len().min(12)];
360	        let first_line = desc.lines().next().unwrap_or(""); // OK: obvious
361	        let display_title = if first_line.is_empty() {
362	            "(no description set)"
363	        } else {
364	            first_line
365	        };
366	
367	        let current_ochid = common::extract_ochid(&commit);
368	
369	        let status = if let Some(ref ochid_val) = current_ochid {
370	            let bare = extract_bare_id(ochid_val);
371	            if bare == "lost" {
372	                CommitStatus::Lost
373	            } else if bare == "none" {
374	                CommitStatus::None_
375	            } else {
376	                // Every `ochid:`, since a Land's agent commit has several.
377	                let mut wrong = Vec::new();
378	                for value in extract_ochids(desc) {
379	                    let id = extract_bare_id(&value);
380	                    if id == "lost" || id == "none" {
381	                        continue;
382	                    }
383	                    let issues = validate_ochid(
384	                        &value,
385	                        &other_forms,
386	                        params.id_len,
387	                        &other_workspace,
388	                        &other_repo,
389	                    );
390	                    if issues.any() {
391	                        wrong.push(issues.summary());
392	                    }
393	                }
394	                let links = if common::is_bot_dir(repo_path) {
395	                    LinkFindings::default()
396	                } else {
397	                    link_findings(
398	                        repo_path,
399	                        &other_repo_path,
400	                        &commit_id.hex(),
401	                        desc,
402	                        params.id_len,
403	                    )?
404	                };
405	                wrong.extend(links.wrong);
406	                wrong.dedup();
407	                if wrong.is_empty() {
408	                    for note in &links.notes {
409	                        info!("note {change_short}  {note}");
410	                    }
411	                    CommitStatus::Ok
412	                } else {
413	                    CommitStatus::NeedsFixed(wrong.join("; "))
414	                }
415	            }
416	        } else {
417	            match find_matching_commit(&commit, &other_workspace, &other_repo)? {
418	                TitleMatch::NoTitle => CommitStatus::MissingNoTitle,
419	                TitleMatch::One(id) => {
420	                    let short_id = &id[..id.len().min(params.id_len)];
421	                    CommitStatus::MissingWithMatch(format!("{other_prefix}{short_id}"))
422	                }
423	                TitleMatch::Ambiguous(n) => CommitStatus::MissingAmbiguous(n),
424	                TitleMatch::None => CommitStatus::MissingNoMatch,
425	            }
426	        };
427	
428	        match status {
429	            CommitStatus::Ok => {
430	                valid += 1;
431	                info!("ok   {change_short}  {display_title}");
432	            }
433	            CommitStatus::Lost => {
434	                lost += 1;
435	                info!("lost {change_short}  {display_title}");
436	            }
437	            CommitStatus::None_ => {
438	                none += 1;
439	                info!("none {change_short}  {display_title}");
440	            }
441	            CommitStatus::NeedsFixed(summary) => {
442	                issues_count += 1;
443	                info!("err  {change_short}  {display_title}  [{summary}]");
444	            }
445	            CommitStatus::MissingWithMatch(ochid) => {
446	                missing += 1;
447	                info!("miss {change_short}  {display_title}  [match: {ochid}]");
448	            }
449	            CommitStatus::MissingNoTitle => {
450	                missing += 1;
451	                info!("miss {change_short}  {display_title}");
452	            }
453	            CommitStatus::MissingAmbiguous(n) => {
454	                missing += 1;
455	                info!("miss {change_short}  {display_title}  [{n} title matches, ambiguous]");
456	            }
457	            CommitStatus::MissingNoMatch => {
458	                missing += 1;
459	                info!("miss {change_short}  {display_title}  [no matching title in other repo]");
460	            }
461	        }
462	    }
463	
464	    let total = valid + lost + none + issues_count + missing;
465	    if total > 10 {
466	        info!("{col_header}");
467	    }
468	    info!("");
469	    info!(
470	        "{valid} valid, {lost} lost, {none} none, {issues_count} issues, {missing} missing \
471	         (of {} total)",
472	        ids.len()
473	    );
474	    Ok(issues_count)
475	}
