//! `push` subcommand: publish a rung's pair. It carries no
//! description and writes none, so what was reviewed is what goes
//! out.
//!
//! `vc-x1 commit` makes the pair, the work commit and the agent
//! commit, each naming the other, or the work half alone with its
//! trailer naming the agent `@`. Each trailer is fixed before push
//! runs, so the two halves are independent, and `push -s b` is
//! `push -s a` then `push -s w`, the order the pair is completed in:
//!
//! - the agent half completes the agent commit by the state it
//!   finds, folding the journal into a committed partner (`commit
//!   -s b`) unless the partner is linked by an `ocid:` or names several
//!   commits, since a fold changes its SHA, or committing it as the partner with the work commit's
//!   own text when the agent `@` is the change the work commit names
//!   (`commit -s w`) or the agent repo changed since, then sets and
//!   pushes `main`;
//! - the work half checks its trailer names the partner, restamping
//!   the unpublished work commit when it does not, said out loud,
//!   then sets and pushes the bookmark `@-` sits on, or the one
//!   named, a new name created there.
//!
//! Before either: a work `@` that is not empty is refused, being a
//! fix to fold or the next rung, the user's call, and so is a work
//! `@-` with no `ochid:` trailer, which is not a pair's commit. Each
//! half restores the repo it touched from a `jj op` snapshot when a
//! stage fails before its own push, and from a push on the remote
//! boundary is crossed. Rerunning is always safe: a half whose work
//! is done finds nothing to do.
//!
//! `-r` names another commit, already made, and only a name goes out
//! for it, the bookmark at it or a new one: the pair's checks are the
//! work `@-`'s.
//!
//! `-s` is required: `b` both halves, `a` the agent half, `w` the
//! work half, and `p` a plain repo's `@-` on its bookmark, no
//! trailer asked for.

use std::path::{Path, PathBuf};

======
/// so rewriting it is a remote rewrite.
pub fn is_published(repo: &Path, rev: &str) -> Result<bool, Box<dyn std::error::Error>> {
    jj::matches(repo, &format!("({rev}) & ::remote_bookmarks()"))
}

/// The work commit of a pair: the work `@-`, its change id, the bare
/// change id its trailer names, and all its trailers. `None` when
/// `@-` carries no trailer, so is not a pair's.
#[derive(Debug, Clone)]
pub struct WorkCommit {
    pub chid: String,
    pub stamped: String,
    /// All it carries, which a rewrite keeps.
    pub trailers: Trailers,
}

/// Read the work commit of the pair, `None` when it has no trailer.
pub fn work_commit(pair: &Pair) -> Result<Option<WorkCommit>, Box<dyn std::error::Error>> {
    let desc = jj::desc_of(&pair.work, "@-")?;
    let Some(trailer) = extract_ochid_from_desc(&desc) else {
        return Ok(None);
    };
    Ok(Some(WorkCommit {
        chid: jj::chid_of(&pair.work, "@-")?,
        stamped: extract_bare_id(&trailer).to_string(),
        trailers: Trailers::of(&desc),
    }))
}

/// Where the agent half of a pair stands.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Partner {
    /// The agent `@-` names the work commit, the pair made at once
    /// (`commit -s b`): the journal in `@` folds into it. Its id.
    Committed(String),
    /// The agent `@-` names the work commit and a Land made it: it
    /// names several, or the work commit's `ocid:` links it, so the
    /// journal in `@` stays out, since a fold changes its SHA. Its id.
    Landed(String),
    /// The agent `@` is the change the work commit names (`commit
    /// -s w`): the journal is the partner, for push to commit. Its id.
    Pending(String),
    /// Neither: the agent repo changed since the commit, so the work
    /// commit names a change that is no longer the partner.
    Changed { stamped: String, agent_at: String },
}

/// Read where the agent half stands for `work`. Reading the agent
/// `@` snapshots it, so a file the size limit refuses stops the
/// caller here, before any mutation.
pub fn partner(pair: &Pair, work: &WorkCommit) -> Result<Partner, Box<dyn std::error::Error>> {
    let agent_at = jj::chid_of(&pair.agent, "@")?;
    let ochids = extract_ochids(&jj::desc_of(&pair.agent, "@-")?);
    let names_work = ochids
        .last()
        .is_some_and(|o| extract_bare_id(o) == work.chid);
    Ok(
        if names_work && (ochids.len() > 1 || work.trailers.ocid.is_some()) {
            Partner::Landed(jj::chid_of(&pair.agent, "@-")?)
        } else if names_work {
            Partner::Committed(jj::chid_of(&pair.agent, "@-")?)
        } else if agent_at == work.stamped {
            Partner::Pending(agent_at)
        } else {
            Partner::Changed {
                stamped: work.stamped.clone(),
                agent_at,
            }
        },
    )
}

/// One repo's `jj op` id, captured before a half's first mutation,
/// to restore that repo alone if a stage fails before its remote
/// leg. A half restores only the repo it touched, since the other
/// may have moved on, a session journal writing to it.
#[derive(Debug)]
pub struct Snapshot {
    repo: PathBuf,
    op: String,
}

