94	/// remote unless `--yes` or a dry run, update, and sort every commit in
95	/// the summary.
96	pub fn trailers(
97	    ctx: &mut Context,
98	    params: &TrailersParams,
99	) -> Result<(), Box<dyn std::error::Error>> {
100	    debug!("trailers: enter {params:?}");
101	    let work = params.pair.work.as_path();
102	    let trunk = crate::commit::configured_trunk(work)?;
103	    let revset = match &params.range {
104	        Some(r) if r.contains("..") || r.contains("::") => r.clone(),
105	        Some(r) => format!("{trunk}..({r})"),
106	        None => format!("{trunk}..@-"),
107	    };
108	    let remote_trunk = format!("{trunk}@origin");
109	    if !params.yes
110	        && jj::rev_exists(work, &remote_trunk)?
111	        && jj::matches(work, &format!("({revset}) & ::{remote_trunk}"))?
112	    {
