119	        }
120	        info!("trailers: [dry-run] {reaches}, which the run takes --yes for");
121	    }
122	    if repo_url_for(&params.pair.agent)?.is_none() {
123	        info!("trailers: the agent repo has no `origin` to link, so no `ocid:`");
124	    }
