130	        &params.pair,
131	        &Update {
132	            label: "trailers",
133	            revset: &revset,
134	            add: true,
135	            agent_at_committed: false,
136	            dry: params.dry_run,
137	        },
138	    )?;
139	    let verb = if params.dry_run {
140	        "would change"
141	    } else {
142	        "changed"
143	    };
144	    info!(
145	        "trailers: {verb} {} of {} commit(s) in '{revset}', {} already current",
146	        outcome.changed,
147	        outcome.changed + outcome.current,
148	        outcome.current
149	    );
150	    for (chid, value) in &outcome.unresolved {
151	        let why = match extract_bare_id(value) {
152	            "lost" | "none" => "a marker naming no partner",
153	            _ => "which names no one agent commit",
154	        };
155	        info!("trailers: {chid} keeps `ochid: {value}`, {why}, so its `ocid:` is left as it is");
156	    }
157	    for chid in &outcome.no_ochid {
158	        info!("trailers: {chid} has no `ochid:`, so it links its parents alone");
159	    }
160	    Ok(())
161	}
