163	/// What [`update`] did with each commit, for the summary.
164	#[derive(Debug, Default, PartialEq, Eq)]
165	pub(crate) struct Outcome {
166	    /// Commits whose trailers changed, or would in a dry run.
167	    pub changed: usize,
168	    /// Commits already as they would be stamped.
169	    pub current: usize,
170	    /// Each `ochid:` kept as it is, naming no one agent commit, by the
171	    /// change id of the commit carrying it.
172	    pub unresolved: Vec<(String, String)>,
173	    /// Commits with no `ochid:`, their `pcid:` lines alone stamped.
174	    pub no_ochid: Vec<String>,
175	}
176	
177	/// What [`update`] does, and to which commits.
178	pub(crate) struct Update<'a> {
179	    /// How messages name the command.
180	    pub label: &'a str,
181	    /// The work commits.
182	    pub revset: &'a str,
183	    /// Stamp `ocid:` and `pcid:` on a commit lacking them, which a Land
184	    /// does not, a commit with no links having asked for none.
185	    pub add: bool,
186	    /// A dry run of a Land: the agent `@` counts as committed, so what
187	    /// names it reads as set, though no SHA exists to show.
188	    pub agent_at_committed: bool,
189	    pub dry: bool,
190	}
191	
192	/// Rewrite the trailers of each commit in the range, oldest first,
193	/// its tree checked unchanged, and return what became of each. Rerunning
194	/// finds nothing to do. A failure restores the work repo.
195	pub(crate) fn update(
196	    ctx: &mut Context,
197	    pair: &Pair,
198	    u: &Update,
199	) -> Result<Outcome, Box<dyn std::error::Error>> {
200	    let (work, agent) = (pair.work.as_path(), pair.agent.as_path());
201	    let label = u.label;
202	    // By change id, since a rewrite changes the SHAs of what is above it.
203	    let chids = jj::cids_of(work, u.revset)?
204	        .iter()
205	        .map(|rev| jj::chid_of(work, rev))
206	        .collect::<Result<Vec<_>, _>>()?;
207	    let agent_url = repo_url_for(agent)?;
208	    let agent_at = jj::chid_of(agent, "@")?;
209	    let placeholder = ocid_placeholder_for(agent)?;
210	    let snapshot = crate::pair::Snapshot::take(work)?;
211	    let mut outcome = Outcome::default();
212	    for chid in &chids {
213	        let desc = jj::desc_of(work, chid)?;
214	        let old = Trailers::of(&desc);
215	        if old.ochids.is_empty() {
216	            if !u.add {
217	                outcome.current += 1;
218	                continue;
219	            }
220	            outcome.no_ochid.push(chid.clone());
221	        }
222	        // Each `ochid:` as the 12 character change id of the one agent
223	        // commit it names, and `partner` the last one's, as `ocid:` links.
224	        let mut ochids = Vec::new();
225	        let mut partner = None;
226	        for value in &old.ochids {
227	            let id = extract_bare_id(value);
228	            partner = match is_change_id_form(id) || is_commit_id_form(id) {
229	                true => jj::one_chid(agent, id)?,
230	                false => None,
231	            };
232	            match &partner {
233	                Some(full) => ochids.push(full.clone()),
234	                None => {
235	                    ochids.push(value.clone());
236	                    outcome.unresolved.push((chid.clone(), value.clone()));
237	                }
238	            }
239	        }
240	        let ocid = match &partner {
241	            _ if !u.add && old.ocid.is_none() => None,
242	            None => old.ocid.clone(),
243	            Some(p) if *p == agent_at && u.agent_at_committed => agent_url
244	                .as_deref()
245	                .map(|url| commit_url(url, "<the agent commit's SHA>")),
246	            Some(p) if *p == agent_at => placeholder.clone(),
247	            Some(p) => match &agent_url {
248	                Some(url) => Some(commit_url(url, &jj::cid_of(agent, p)?)),
249	                None => old.ocid.clone(),
250	            },
251	        };
252	        let pcids = if u.add || !old.pcids.is_empty() {
253	            pcids_for(work, &jj::parent_cids_of(work, chid)?)?
254	        } else {
255	            Vec::new()
256	        };
257	        let new = with_trailers(
258	            &desc,
259	            &Trailers {
260	                ochids,
261	                ocid,
262	                pcids,
263	            },
264	        );
265	        if new == desc {
266	            outcome.current += 1;
267	            continue;
268	        }
269	        outcome.changed += 1;
270	        if u.dry {
271	            info!("{label}: [dry-run] {chid}:\n{new}");
272	            continue;
273	        }
274	        if crate::pair::is_published(work, chid)? {
275	            warn!("{label}: {chid} is published, so its copy on the remote goes stale");
276	        }
277	        info!("{label}: update the trailers of {chid}");
278	        let tree = jj::tree_of(work, chid)?;
279	        let stamped = ctx.session(work)?.describe(chid, &new).and_then(|_| {
280	            match jj::tree_of(work, chid)? == tree {
281	                true => Ok(()),
282	                false => {
283	                    Err(format!("{label}: updating {chid}'s trailers changed its tree").into())
284	                }
285	            }
286	        });
287	        if let Err(e) = stamped {
288	            snapshot.restore(label, e.as_ref());
289	            return Err(e);
290	        }
291	    }
292	    Ok(outcome)
293	}
