    let fx = Fixture::new("sp-dry-run");
    std::fs::write(fx.bot.join("tail.txt"), "session tail\n").expect("write");
    let main_before = cid(&fx.bot, "main");
    let mut args = parse(&["vc-x1", "squash-push", "-s", "a", "--dry-run"]);
    args.repo = Some(fx.work.clone());
