// Report where the bookmark stands against origin before touching
// anything. A bookmark ahead of origin is the common case, a Land
// made locally and published after the session, so it is reported,
// not warned: preflight has already refused a forced push, so
// without --force the run is a fast-forward. With --force a forced
// push is the one worth a warning. Suppressed when run as push's
// `squash-push-bot` stage (see `at_rest`).
if params.at_rest {
    match crate::common::bookmark_publish_state(&params.repo, bookmark)? {
        crate::common::PublishState::InSync => {}
        crate::common::PublishState::NeverPushed => info!(
            "squash-push: '{bookmark}' has never been pushed to origin: this run will \
             publish it"
        ),
        crate::common::PublishState::Mismatch { local, remote } => {
            let (local, remote) = (&local[..local.len().min(12)], &remote[..remote.len().min(12)]);
            match forced_push(&params.repo, sq, bookmark)? {
                Some(why) => warn!(
                    "squash-push: the push of '{bookmark}' is forced, since {why}: \
                     --force rewrites '{bookmark}@origin' ({remote})"
                ),
                None => info!(
                    "squash-push: '{bookmark}' ({local}) is ahead of '{bookmark}@origin' \
                     ({remote}): this run will publish it"
                ),
            }
        }
    }
}

