    /// Print what the precheck found and the steps it would take,
    /// and change nothing.
    pub dry_run: bool,
    /// The `--yes` flag itself, never the config key: a forced push
    /// confirmed in advance. Without it an at-rest run asks, and push's
    /// stage refuses.
    pub forced_yes: bool,
}

