        return Err(e);
    }
    step_gate(params, "the work bookmark", "the work push")?;
    crate::common::verify_tracking(&pair.work, bookmark)?;
    info!("push work: git push --bookmark {bookmark} -R {work_arg}");
    ctx.session(&pair.work)?.git_push_bookmark(bookmark)?;
    Ok(())
}

