/// Push `bookmark`, forced only when `forced`, the caller's user having
/// said yes to it. Unforced, a push that would be forced is refused.
fn push_bookmark(
    ctx: &mut Context,
    repo: &Path,
    bookmark: &str,
    forced: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    if forced {
        ctx.session(repo)?.git_push_bookmark_forced(bookmark)
    } else {
        ctx.session(repo)?.git_push_bookmark(bookmark)
    }
}

