fn both() -> Scope {
    Scope(vec![Side::Work, Side::Bot])
}

/// Standard test params: the line's bookmark, `-s b`, no gates.
fn test_params() -> PushParams {
    PushParams {
        revision: None,
        bookmark: None,
        repo: None,
        scope: RepoScope::Sides(both()),
        step: false,
        dry_run: false,
        yes: true,
    }
}
    make_pair(&fx, "feat: by revision", true);
    let work_main = cid(&fx.work, "main");
    let mut params = test_params();
    params.bookmark = Some("@-".to_string());

    let err = push(
        &mut test_ctx(),
        &PushParams {
            repo: Some(fx.work.clone()),
            ..params
        },
    )
    .expect_err("refused")
    .to_string();
    assert!(err.contains("is a revision, not a bookmark name"), "{err}");
    assert!(err.contains("`-r @-`"), "{err}");
    assert_eq!(cid(&fx.work, "main"), work_main);
}

